// Получаем ответ API (purchase details)
const httpData = $input.first().json;

// Получаем данные из текущего batch-элемента
const batch = $('Split In Batches').first().json;

const nicheId = parseInt(batch.niche_id);
const purchaseNum = batch.purchase_number;
const contractPrice = parseFloat(batch.contract_price);

// НМЦК — пробуем оба варианта нотации (CamelCase ЕИС / snake_case API)
const maxPrice = parseFloat(httpData.maxPrice || httpData.max_price || 0);

let dumpingPct = 0;
if (maxPrice > 0 && contractPrice > 0) {
  dumpingPct = Math.round(((maxPrice - contractPrice) / maxPrice) * 1000) / 10;
}

return [{
  json: {
    niche_id: nicheId,
    purchase_number: purchaseNum,
    max_price: maxPrice,
    contract_price: contractPrice,
    dumping_pct: dumpingPct
  }
}];

